<script setup lang="ts">
import { computed, inject, ref, watch } from 'vue';
import { RouterLink, useRoute, useRouter } from 'vue-router';
import Button from 'primevue/button'; import InputText from 'primevue/inputtext'; import Message from 'primevue/message'; import MultiSelect from 'primevue/multiselect'; import ProgressSpinner from 'primevue/progressspinner'; import Select from 'primevue/select'; import Tag from 'primevue/tag'; import Textarea from 'primevue/textarea';
import { useToast } from 'primevue/usetoast';
import { addIssueComment, assignIssue, getIssue, getIssueComments, getIssueHistory, getProjectLabels, transitionIssue, updateIssue } from '../../api/issues';
import type { IssueCommentInfo, IssueHistoryInfo, IssueInfo, IssueLabelInfo, IssuePriority, IssueType } from '../../api/types';
import { projectWorkspaceKey } from '../../features/projects/projectContext';
import { useI18n } from 'vue-i18n';
import { useDomainLabels } from '../../i18n/domain';

const context=inject(projectWorkspaceKey)!;const route=useRoute();const router=useRouter();const toast=useToast();
const{t,locale}=useI18n();const{issueStatusLabel,issueTypeOptions,priorityOptions}=useDomainLabels();
const issue=ref<IssueInfo|null>(null);const history=ref<IssueHistoryInfo[]>([]);const comments=ref<IssueCommentInfo[]>([]);const loading=ref(true);const error=ref('');
const title=ref('');const description=ref('');const type=ref<IssueType>('Feature');const priority=ref<IssuePriority>('Medium');const assignee=ref<string|null>(null);const dueDate=ref('');const comment=ref('');const labels=ref<IssueLabelInfo[]>([]);const labelIds=ref<string[]>([]);
const issueId=computed(()=>String(route.params.issueId));const assigneeOptions=computed(()=>context.members.value.map(item=>({label:item.email,value:item.userId})));
const backTarget=computed(()=>{const from=typeof route.query.from==='string'?route.query.from:'';return from.startsWith(`/projects/${context.project.value.id}/issues`)?from:{name:'project-issues',params:{projectId:context.project.value.id}};});
function fill(item:IssueInfo){title.value=item.title;description.value=item.description??'';type.value=item.type;priority.value=item.priority;assignee.value=item.assigneeUserId;dueDate.value=item.dueDate?item.dueDate.slice(0,16):'';labelIds.value=item.labels.map(label=>label.id);}
async function load(){loading.value=true;error.value='';issue.value=null;try{const [item,changes,discussion,projectLabels]=await Promise.all([getIssue(context.project.value.id,issueId.value),getIssueHistory(context.project.value.id,issueId.value),getIssueComments(context.project.value.id,issueId.value),getProjectLabels(context.project.value.id)]);if(!item)throw new Error(t('issues.unavailable'));issue.value=item;history.value=changes??[];comments.value=discussion??[];labels.value=projectLabels??[];fill(item);}catch(cause){error.value=cause instanceof Error?cause.message:t('issues.unavailable');}finally{loading.value=false;}}
async function refresh(updated:IssueInfo){issue.value=updated;fill(updated);history.value=(await getIssueHistory(context.project.value.id,updated.id))??[];}
async function save(){if(!issue.value)return;try{let updated=await updateIssue(context.project.value.id,issue.value.id,{title:title.value,description:description.value.trim()||null,type:type.value,priority:priority.value,dueDate:dueDate.value?new Date(dueDate.value).toISOString():null,labelIds:labelIds.value});if(issue.value.canAssign&&assignee.value!==issue.value.assigneeUserId)updated=await assignIssue(context.project.value.id,issue.value.id,assignee.value);if(updated)await refresh(updated);toast.add({severity:'success',detail:t('issues.updated'),life:2600});}catch(cause){notify(cause,t('common.error'));}}
async function move(status:string){if(!issue.value)return;try{const updated=await transitionIssue(context.project.value.id,issue.value.id,status);if(updated)await refresh(updated);}catch(cause){notify(cause,t('issues.transitionFailed'));}}
async function addComment(){if(!issue.value||!comment.value.trim())return;try{const created=await addIssueComment(context.project.value.id,issue.value.id,comment.value);if(created)comments.value.push(created);comment.value='';}catch(cause){notify(cause,t('common.error'));}}
function notify(cause:unknown,fallback:string){toast.add({severity:'error',detail:cause instanceof Error?cause.message:fallback,life:3600});}
watch(issueId,load,{immediate:true});
</script>
<template><section class="issue-detail-page"><div v-if="loading" class="detail-state"><ProgressSpinner :aria-label="t('issues.loading')"/><p>{{t('issues.loading')}}</p></div><Message v-else-if="error" severity="error"><strong>{{t('issues.unavailable')}}</strong> {{error}} <Button :label="t('issues.back')" link @click="router.push(backTarget)"/></Message><template v-else-if="issue"><nav class="issue-breadcrumb" aria-label="Issue breadcrumb"><RouterLink :to="{name:'projects'}">{{t('projects.title')}}</RouterLink><i class="pi pi-angle-right"></i><RouterLink :to="{name:'project-overview'}">{{context.project.value.name}}</RouterLink><i class="pi pi-angle-right"></i><a href="#" @click.prevent="router.push(backTarget)">{{t('issues.title')}}</a><i class="pi pi-angle-right"></i><span>{{issue.title}}</span></nav><header class="detail-header"><div><Button :label="t('issues.back')" icon="pi pi-arrow-left" link @click="router.push(backTarget)"/><h2>{{issue.title}}</h2></div><div class="status-actions"><Tag :value="issueStatusLabel(issue.status)"/><Button v-for="next in issue.allowedTransitions" :key="next" :label="t('issues.moveToStatus',{status:issueStatusLabel(next)})" size="small" @click="move(next)"/></div></header><Message v-if="context.project.value.status==='Archived'" severity="warn">{{t('issues.archivedReadOnly')}}</Message><div class="detail-grid"><section class="detail-card"><h3>{{t('issues.details')}}</h3><div class="issue-form"><label>{{t('issues.titleField')}}<InputText v-model="title" :disabled="!issue.canEdit"/></label><label>{{t('issues.descriptionField')}}<Textarea v-model="description" rows="7" :disabled="!issue.canEdit"/></label><div class="form-row"><label>{{t('issues.type')}}<Select v-model="type" :options="issueTypeOptions" option-label="label" option-value="value" :disabled="!issue.canEdit"/></label><label>{{t('issues.priority')}}<Select v-model="priority" :options="priorityOptions" option-label="label" option-value="value" :disabled="!issue.canEdit"/></label></div><label>{{t('issues.assignee')}}<Select v-model="assignee" :options="assigneeOptions" option-label="label" option-value="value" show-clear :placeholder="t('common.unassigned')" :disabled="!issue.canAssign"/></label><label>{{t('issues.labels')}}<MultiSelect v-model="labelIds" :options="labels" option-label="name" option-value="id" display="chip" :disabled="!issue.canEdit"/></label><label>{{t('issues.dueDate')}}<InputText v-model="dueDate" type="datetime-local" :disabled="!issue.canEdit"/></label><Button :label="t('issues.save')" :disabled="!issue.canEdit&&!issue.canAssign" @click="save"/></div></section><aside class="detail-card metadata"><h3>{{t('issues.metadata')}}</h3><dl><dt>{{t('issues.reporter')}}</dt><dd>{{issue.creatorEmail}}</dd><dt>{{t('issues.createdAt')}}</dt><dd>{{new Date(issue.createdAt).toLocaleString(locale)}}</dd><dt>{{t('issues.updatedAt')}}</dt><dd>{{new Date(issue.updatedAt).toLocaleString(locale)}}</dd></dl></aside></div><div class="activity-grid"><section class="detail-card"><h3>{{t('issues.comments')}}</h3><div class="timeline"><article v-for="item in comments" :key="item.id"><strong>{{item.authorEmail}}</strong><small>{{new Date(item.createdAt).toLocaleString(locale)}}</small><p>{{item.content}}</p></article><p v-if="!comments.length">{{t('issues.noComments')}}</p></div><div v-if="issue.canComment" class="comment-form"><Textarea v-model="comment" rows="3" :placeholder="t('issues.commentPlaceholder')" :aria-label="t('issues.commentPlaceholder')"/><Button :label="t('issues.comment')" :disabled="!comment.trim()" @click="addComment"/></div></section><section class="detail-card"><h3>{{t('issues.history')}}</h3><div class="timeline"><article v-for="item in history" :key="item.id"><strong>{{item.actorEmail}} · {{item.changeType}}</strong><small>{{new Date(item.createdAt).toLocaleString(locale)}}</small><p>{{item.fieldName||t('issues.title')}}: {{item.previousValue??'—'}} → {{item.newValue??'—'}}</p></article><p v-if="!history.length">{{t('issues.noHistory')}}</p></div></section></div></template></section></template>
<style scoped>.issue-detail-page{display:grid;gap:1rem}.detail-state{min-height:18rem;display:grid;place-content:center;justify-items:center}.issue-breadcrumb,.status-actions{display:flex;align-items:center;gap:.55rem;flex-wrap:wrap}.issue-breadcrumb{font-size:.9rem;color:var(--p-text-muted-color)}.detail-header{display:flex;align-items:flex-start;justify-content:space-between;gap:1rem}.detail-header h2{margin:.25rem 0}.detail-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(15rem,1fr);gap:1rem}.activity-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.detail-card{border:1px solid var(--p-content-border-color);border-radius:var(--p-border-radius);padding:1rem;min-width:0}.detail-card h3{margin-top:0}.issue-form,.issue-form label,.timeline{display:grid;gap:.65rem}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:.75rem}.metadata dl{display:grid;grid-template-columns:auto 1fr;gap:.7rem}.metadata dt{color:var(--p-text-muted-color)}.timeline article{border-bottom:1px solid var(--p-content-border-color);padding:.6rem 0}.timeline small{display:block;color:var(--p-text-muted-color)}.timeline p{white-space:pre-wrap}.comment-form{display:grid;gap:.6rem;margin-top:1rem}@media(max-width:850px){.detail-grid,.activity-grid,.form-row{grid-template-columns:1fr}.detail-header{display:grid}}</style>
